from wile_e_interfaces.msg import RoboclawCommand
import rclpy
from rclpy.node import Node
from rclpy.qos import QoSProfile
from wile_e.roboclaw import Roboclaw
import struct

# Initialize serial communication
rc_bicep = Roboclaw("/dev/roboclaw_biceps",38400)
rc_bicep.Open()
rc_forearm = Roboclaw("/dev/roboclaw_forearms",38400)
rc_forearm.Open()
address = 0x80

class RoboclawControllerNode(Node):

    def __init__(self):
        super().__init__('roboclaw_controller')
        qos_profile = QoSProfile(depth=10)
        self.roboclaw_command_subscription = self.create_subscription(
            RoboclawCommand,
            'roboclaw_commands',
            self.roboclaw_control_callback,
            qos_profile)
        self.roboclaw_command_subscription
        
        rc_bicep.ResetEncoders(address)
        rc_bicep.SetEncM1(address,1174)##zero is 80 degrees
        self.get_logger().info(f"PID: {rc_bicep.ReadM1PositionPID(address)}")
        #rc_bicep.SpeedAccelDeccelPositionM1(address,2000,3000,2000,786,1)
        
        rc_forearm.ResetEncoders(address)
        rc_forearm.SetEncM1(address,0)##zero is 0 degrees
        self.get_logger().info(f"PID: {rc_forearm.ReadM1PositionPID(address)}")
        rc_forearm.SpeedAccelDeccelPositionM1(address,2000,3000,2000,628,1)
        
        self.get_logger().info('Roboclaw controller awaiting commands...')

    def roboclaw_control_callback(self, msg):
        ##self.get_logger().info(f"I heard: {msg.left_forearm}")
        #rc_bicep.SpeedAccelDeccelPositionM1(address,88000,8800,88000,msg.left_bicep,1)
        rc_forearm.SpeedAccelDeccelPositionM1(address,28000,2800,28000,msg.left_forearm,1)
        ##self.get_logger().info(f"motor 1: {rc_bicep.ReadEncM1(address)}")
        if msg.left_bicep == 786:
            self.get_logger().info("bicep loop started")


def main(args=None):
    rclpy.init(args=args)

    roboclaw_controller_node = RoboclawControllerNode()

    rclpy.spin(roboclaw_controller_node)

    roboclaw_controller_node.destroy_node()
    rclpy.shutdown()
    ser.close()


if __name__ == '__main__':
    main()
